mkdir -p src; cat > src/main.c <<'CEOF'
/*
 * Reimplementation of the dropbear server command-line interface.
 * This implementation reproduces the observable behavior of the original
 * Dropbear SSH server binary for argument parsing, usage/version output,
 * early-exit error messages, and the startup log sequence.  It does not
 * implement the actual SSH protocol.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <strings.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <grp.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define DROPBEAR_VERSION "2025.89"
#define DEFAULT_RECV_WINDOW 24576
#define MAX_RECV_WINDOW (10 * 1024 * 1024)
#define MAX_LISTEN_PORTS 10
#define DEFAULT_PORT "22"
#define DEFAULT_PID_FILE "/var/run/dropbear.pid"

#define RSA_PRIV_FILENAME     "/etc/dropbear/dropbear_rsa_host_key"
#define ECDSA_PRIV_FILENAME   "/etc/dropbear/dropbear_ecdsa_host_key"
#define ED25519_PRIV_FILENAME "/etc/dropbear/dropbear_ed25519_host_key"

static const char *prog_name = "dropbear";

static void timestamp_prefix(char *out, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(out, len, "%b %d %H:%M:%S", &tm);
}

static void log_line(const char *fmt, va_list ap) {
    char ts[64];
    timestamp_prefix(ts, sizeof ts);
    fprintf(stderr, "[%d] %s ", (int)getpid(), ts);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
}

static void dblog(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    log_line(fmt, ap);
    va_end(ap);
}

static void early_exit(const char *fmt, ...) {
    char ts[64];
    timestamp_prefix(ts, sizeof ts);
    fprintf(stderr, "[%d] %s Early exit: ", (int)getpid(), ts);
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
    exit(1);
}

static void print_header(void) {
    fprintf(stderr,
        "Dropbear server v" DROPBEAR_VERSION
        " https://matt.ucc.asn.au/dropbear/dropbear.html\n");
}

static void print_usage(void) {
    print_header();
    fprintf(stderr, "Usage: %s [options]\n", prog_name);
    fprintf(stderr,
        "-b bannerfile\tDisplay the contents of bannerfile before user login\n"
        "\t\t(default: none)\n"
        "-r keyfile      Specify hostkeys (repeatable)\n"
        "\t\tdefaults: \n"
        "\t\t- rsa " RSA_PRIV_FILENAME "\n"
        "\t\t- ecdsa " ECDSA_PRIV_FILENAME "\n"
        "\t\t- ed25519 " ED25519_PRIV_FILENAME "\n"
        "-D\t\tDirectory containing authorized_keys file\n"
        "-R\t\tCreate hostkeys as required\n"
        "-F\t\tDon't fork into background\n"
        "-e\t\tPass on server process environment to child process\n"
        "(Syslog support not compiled in, using stderr)\n"
        "-m\t\tDon't display the motd on login\n"
        "-w\t\tDisallow root logins\n"
        "-G\t\tRestrict logins to members of specified group\n"
        "-s\t\tDisable password logins\n"
        "-g\t\tDisable password logins for root\n"
        "-B\t\tAllow blank password logins\n"
        "-t\t\tEnable two-factor authentication (both password and public key required)\n"
        "-T\t\tMaximum authentication tries (default 10)\n"
        "-j\t\tDisable local port forwarding\n"
        "-k\t\tDisable remote port forwarding\n"
        "-a\t\tAllow connections to forwarded ports from any host\n"
        "-c command\tForce executed command\n"
        "-p [address:]port\n"
        "\t\tListen on specified tcp port (and optionally address),\n"
        "\t\tup to %d can be specified\n"
        "\t\t(default port is %s if none specified)\n"
        "-P PidFile\tCreate pid file PidFile\n"
        "\t\t(default %s)\n"
        "-l <interface>\n"
        "\t\tinterface to bind on\n"
        "-i\t\tStart for inetd\n"
        "-W <receive_window_buffer> (default %d, larger may be faster, max 10MB)\n"
        "-K <keepalive>  (0 is never, default 0, in seconds)\n"
        "-I <idle_timeout>  (0 is never, default 0, in seconds)\n"
        "-z    disable QoS\n"
        "-V    Version\n",
        MAX_LISTEN_PORTS, DEFAULT_PORT, DEFAULT_PID_FILE, DEFAULT_RECV_WINDOW);
}

static void print_version(void) {
    fprintf(stderr, "Dropbear v" DROPBEAR_VERSION "\n");
}

/* Parse an unsigned integer like strtoul but require that the whole
 * string parses.  Returns 0 on success, -1 on failure. */
static int parse_uint(const char *s, unsigned int *out) {
    if (s == NULL || *s == '\0') return -1;
    char *end = NULL;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return -1;
    /* reject leading '-' (strtoul would accept "-1" wrap) */
    for (const char *p = s; *p; p++) {
        if (*p == '-') return -1;
    }
    if (v > 0xFFFFFFFFUL) return -1;
    *out = (unsigned int)v;
    return 0;
}

struct server_opts {
    const char *banner_file;
    const char *keyfiles[16];
    int n_keyfiles;
    const char *authkey_dir;
    int create_keys;
    int no_fork;
    int pass_env;
    int no_motd;
    int no_root;
    const char *restrict_group;
    int no_password;
    int no_root_password;
    int allow_blank_password;
    int require_2fa;
    unsigned int max_auth_tries;
    int no_local_fwd;
    int no_remote_fwd;
    int allow_remote_fwd_any;
    const char *forced_command;
    const char *ports[MAX_LISTEN_PORTS];
    int n_ports;
    const char *pid_file;
    const char *bind_iface;
    int inetd_mode;
    unsigned int recv_window;
    unsigned int keepalive_secs;
    unsigned int idle_timeout_secs;
    int disable_qos;
};

static struct server_opts opts;

/* split "host:port" at the final ':', writing host and port pointers.
 * If there's no colon, host=NULL and port=s.
 * Returns 0 on success, -1 if port part is empty. */
static int split_host_port(const char *s, char **host_out, char **port_out) {
    if (s == NULL) return -1;
    const char *last = strrchr(s, ':');
    if (last == NULL) {
        *host_out = NULL;
        *port_out = strdup(s);
        return 0;
    }
    size_t hostlen = last - s;
    const char *portstr = last + 1;
    if (*portstr == '\0') {
        return -1;
    }
    *host_out = (char *)malloc(hostlen + 1);
    memcpy(*host_out, s, hostlen);
    (*host_out)[hostlen] = '\0';
    *port_out = strdup(portstr);
    return 0;
}

static void validate_port(const char *spec) {
    char *host = NULL, *port = NULL;
    if (split_host_port(spec, &host, &port) != 0) {
        early_exit("Bad port");
    }
    free(host);
    free(port);
}

/* Custom argv parser following dropbear's behaviour.
 * - Short options grouped in one argv token (e.g. -abc).
 * - When an option takes an argument, the remainder of the same token
 *   (or the next argv token if none) is consumed.
 * - Invalid option prints "Invalid option -X" to stderr, then usage, exit 1.
 * - Missing argument triggers the log-formatted "Early exit: Missing argument".
 * - "-V" exits immediately after printing version.
 * - "-h" exits immediately after printing usage, with status 0.
 * - "--" (or any "-" followed by a '-' character) is treated as invalid.
 */

static const char options_needing_arg[] = "brDGcpPlWKITz";
/* note: -z is in usage as "disable QoS" (no arg).  Keep separate list. */

static int takes_arg(char c) {
    switch (c) {
        case 'b': case 'r': case 'D': case 'G': case 'c':
        case 'p': case 'P': case 'l': case 'W': case 'K':
        case 'I': case 'T':
            return 1;
        default:
            return 0;
    }
}

static void missing_argument(void) {
    early_exit("Missing argument");
}

static const char *consume_arg(int argc, char **argv, int *pi, const char *rest) {
    /* rest is the portion of the current argv token after the option char.
     * If non-empty, use it as the argument.  Otherwise advance to next argv. */
    if (rest && *rest) {
        return rest;
    }
    (*pi)++;
    if (*pi >= argc) {
        missing_argument();
    }
    return argv[*pi];
}

static void parse_args(int argc, char **argv) {
    opts.max_auth_tries = 10;
    opts.recv_window = DEFAULT_RECV_WINDOW;

    int i = 1;
    while (i < argc) {
        const char *arg = argv[i];
        if (arg[0] != '-' || arg[1] == '\0') {
            /* Unknown positional argument - treat as invalid like dropbear. */
            fprintf(stderr, "Invalid option %s\n", arg);
            print_usage();
            exit(1);
        }
        int j = 1;
        int consumed_arg = 0;
        while (arg[j] && !consumed_arg) {
            char c = arg[j];
            const char *rest = &arg[j + 1];
            switch (c) {
                case 'V':
                    print_version();
                    exit(0);
                case 'h':
                    print_usage();
                    exit(0);
                case 'b': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    opts.banner_file = v;
                    consumed_arg = 1;
                    break;
                }
                case 'r': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    if (opts.n_keyfiles < (int)(sizeof(opts.keyfiles)/sizeof(opts.keyfiles[0])))
                        opts.keyfiles[opts.n_keyfiles++] = v;
                    consumed_arg = 1;
                    break;
                }
                case 'D': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    opts.authkey_dir = v;
                    consumed_arg = 1;
                    break;
                }
                case 'G': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    opts.restrict_group = v;
                    consumed_arg = 1;
                    break;
                }
                case 'c': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    opts.forced_command = v;
                    consumed_arg = 1;
                    break;
                }
                case 'p': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    validate_port(v);
                    if (opts.n_ports < MAX_LISTEN_PORTS)
                        opts.ports[opts.n_ports++] = v;
                    consumed_arg = 1;
                    break;
                }
                case 'P': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    opts.pid_file = v;
                    consumed_arg = 1;
                    break;
                }
                case 'l': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    opts.bind_iface = v;
                    consumed_arg = 1;
                    break;
                }
                case 'W': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    unsigned int w = 0;
                    if (parse_uint(v, &w) != 0 || w == 0) {
                        dblog("Bad recv window '%s', using %d", v, DEFAULT_RECV_WINDOW);
                        opts.recv_window = DEFAULT_RECV_WINDOW;
                    } else if (w > MAX_RECV_WINDOW) {
                        dblog("Bad recv window '%s', using %d", v, MAX_RECV_WINDOW);
                        opts.recv_window = MAX_RECV_WINDOW;
                    } else {
                        opts.recv_window = w;
                    }
                    consumed_arg = 1;
                    break;
                }
                case 'K': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    unsigned int x = 0;
                    if (parse_uint(v, &x) != 0)
                        early_exit("Bad keepalive '%s'", v);
                    opts.keepalive_secs = x;
                    consumed_arg = 1;
                    break;
                }
                case 'I': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    unsigned int x = 0;
                    if (parse_uint(v, &x) != 0)
                        early_exit("Bad idle_timeout '%s'", v);
                    opts.idle_timeout_secs = x;
                    consumed_arg = 1;
                    break;
                }
                case 'T': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    unsigned int x = 0;
                    if (parse_uint(v, &x) != 0)
                        early_exit("Bad maxauthtries '%s'", v);
                    opts.max_auth_tries = x;
                    consumed_arg = 1;
                    break;
                }
                case 'R': opts.create_keys = 1; break;
                case 'F': opts.no_fork = 1; break;
                case 'e': opts.pass_env = 1; break;
                case 'm': opts.no_motd = 1; break;
                case 'w': opts.no_root = 1; break;
                case 's': opts.no_password = 1; break;
                case 'g': opts.no_root_password = 1; break;
                case 'B': opts.allow_blank_password = 1; break;
                case 't': opts.require_2fa = 1; break;
                case 'j': opts.no_local_fwd = 1; break;
                case 'k': opts.no_remote_fwd = 1; break;
                case 'a': opts.allow_remote_fwd_any = 1; break;
                case 'i': opts.inetd_mode = 1; break;
                case 'z': opts.disable_qos = 1; break;
                default:
                    fprintf(stderr, "Invalid option -%c\n", c);
                    print_usage();
                    exit(1);
            }
            j++;
            (void)takes_arg; /* silence unused warning */
        }
        i++;
    }
}

static int try_load_hostkey(const char *path) {
    /* Pretend to load a hostkey.  Return 1 on "success", 0 on failure.
     * We only "succeed" if the file exists and is readable. */
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        return 0;
    }
    close(fd);
    return 1;
}

static int load_hostkeys(void) {
    int loaded = 0;
    if (opts.n_keyfiles > 0) {
        for (int i = 0; i < opts.n_keyfiles; i++) {
            if (try_load_hostkey(opts.keyfiles[i])) {
                loaded++;
            } else {
                dblog("Failed loading %s", opts.keyfiles[i]);
            }
        }
    } else {
        static const char *defaults[] = {
            RSA_PRIV_FILENAME,
            ECDSA_PRIV_FILENAME,
            ED25519_PRIV_FILENAME,
            NULL
        };
        for (int i = 0; defaults[i]; i++) {
            if (try_load_hostkey(defaults[i])) {
                loaded++;
            } else {
                dblog("Failed loading %s", defaults[i]);
            }
        }
    }
    return loaded;
}

static int try_listen_port(const char *spec) {
    char *host = NULL, *port = NULL;
    if (split_host_port(spec, &host, &port) != 0) {
        /* Shouldn't happen - we validated earlier */
        dblog("Failed listening on '%s': Error listening: Bad port", spec);
        free(host); free(port);
        return 0;
    }

    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_PASSIVE;
    int gaierr = getaddrinfo(host, port, &hints, &res);
    if (gaierr != 0) {
        dblog("Failed listening on '%s': Error resolving: %s", port, gai_strerror(gaierr));
        free(host); free(port);
        return 0;
    }

    int any_bound = 0;
    const char *last_err = NULL;
    char errbuf[128];
    for (struct addrinfo *r = res; r; r = r->ai_next) {
        int fd = socket(r->ai_family, r->ai_socktype, r->ai_protocol);
        if (fd < 0) {
            last_err = strerror(errno);
            continue;
        }
        int one = 1;
        setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
        if (bind(fd, r->ai_addr, r->ai_addrlen) != 0) {
            snprintf(errbuf, sizeof errbuf, "%s", strerror(errno));
            last_err = errbuf;
            close(fd);
            continue;
        }
        if (listen(fd, 20) != 0) {
            snprintf(errbuf, sizeof errbuf, "%s", strerror(errno));
            last_err = errbuf;
            close(fd);
            continue;
        }
        any_bound = 1;
        /* leave the socket open - we will close on exit */
    }
    freeaddrinfo(res);

    if (!any_bound) {
        dblog("Failed listening on '%s': Error listening: %s",
              port, last_err ? last_err : "Unknown error");
    }
    free(host); free(port);
    return any_bound;
}

static volatile sig_atomic_t caught_signal = 0;
static void signal_handler(int sig) {
    (void)sig;
    caught_signal = 1;
}

int main(int argc, char **argv) {
    prog_name = argv[0];

    parse_args(argc, argv);

    /* Banner file check */
    if (opts.banner_file) {
        int fd = open(opts.banner_file, O_RDONLY);
        if (fd < 0) {
            dblog("Error opening banner file '%s'", opts.banner_file);
        } else {
            close(fd);
        }
    }

    if (opts.forced_command) {
        dblog("Forced command set to '%s'", opts.forced_command);
    }

    if (opts.bind_iface) {
        dblog("Binding to interface '%s'", opts.bind_iface);
    }

    if (opts.restrict_group) {
        errno = 0;
        struct group *g = getgrnam(opts.restrict_group);
        if (!g) {
            early_exit("Cannot restrict logins to group '%s' as the group does not exist",
                       opts.restrict_group);
        }
    }

    int loaded = load_hostkeys();
    if (loaded == 0) {
        early_exit("No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");
    }

    /* Listen on configured ports. */
    int n_listens = 0;
    if (opts.n_ports == 0) {
        if (try_listen_port(DEFAULT_PORT)) n_listens++;
    } else {
        for (int i = 0; i < opts.n_ports; i++) {
            if (try_listen_port(opts.ports[i])) n_listens++;
        }
    }
    if (n_listens == 0) {
        early_exit("No listening ports available.");
    }

    if (opts.no_fork || opts.inetd_mode) {
        dblog("Not backgrounding");
    } else {
        dblog("Running in background");
        pid_t pid = fork();
        if (pid < 0) {
            early_exit("fork() failed");
        }
        if (pid > 0) {
            /* Parent exits immediately with success. */
            _exit(0);
        }
        /* Child - detach from terminal. */
        setsid();
        int devnull = open("/dev/null", O_RDWR);
        if (devnull >= 0) {
            dup2(devnull, 0);
            dup2(devnull, 1);
            dup2(devnull, 2);
            if (devnull > 2) close(devnull);
        }
    }

    /* Set up signal handlers so we can log "Terminated by signal". */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);

    /* We don't implement SSH; just wait for signals / data. */
    while (!caught_signal) {
        pause();
    }

    early_exit("Terminated by signal");
    return 1;
}
