/* Parse an unsigned integer like strtoul but require that the whole
 * string parses.  Returns 0 on success, -1 on failure. */
static int parse_uint(const char *s, unsigned int *out) {
    if (s == NULL || *s == '\0') return -1;
    char *end = NULL;
