/* split "host:port" at the final ':', writing host and port pointers.
 * If there's no colon, host=NULL and port=s.
 * Returns 0 on success, -1 if port part is empty. */
static int split_host_port(const char *s, char **host_out, char **port_out) {
    if (s == NULL) return -1;
    const char *last = strrchr(s, ':');
    if (last == NULL) {
        *host_out = NULL;
        *port_out = strdup(s);
        return 0;
    }
    size_t hostlen = last - s;
    const char *portstr = last + 1;
    if (*portstr == '\0') {
        return -1;
    }
    *host_out = (char *)malloc(hostlen + 1);
    memcpy(*host_out, s, hostlen);
    (*host_out)[hostlen] = '\0';
    *port_out = strdup(portstr);
    return 0;
}

