                        opts.recv_window = MAX_RECV_WINDOW;
                    } else {
                        opts.recv_window = w;
                    }
                    consumed_arg = 1;
                    break;
                }
                case 'K': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    unsigned int x = 0;
                    if (parse_uint(v, &x) != 0)
                        early_exit("Bad keepalive '%s'", v);
                    opts.keepalive_secs = x;
                    consumed_arg = 1;
                    break;
                }
                case 'I': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    unsigned int x = 0;
                    if (parse_uint(v, &x) != 0)
                        early_exit("Bad idle_timeout '%s'", v);
                    opts.idle_timeout_secs = x;
                    consumed_arg = 1;
                    break;
                }
                case 'T': {
                    const char *v = consume_arg(argc, argv, &i, rest);
                    unsigned int x = 0;
                    if (parse_uint(v, &x) != 0)
                        early_exit("Bad maxauthtries '%s'", v);
                    opts.max_auth_tries = x;
                    consumed_arg = 1;
                    break;
                }
                case 'R': opts.create_keys = 1; break;
                case 'F': opts.no_fork = 1; break;
                case 'e': opts.pass_env = 1; break;
                case 'm': opts.no_motd = 1; break;
                case 'w': opts.no_root = 1; break;
                case 's': opts.no_password = 1; break;
                case 'g': opts.no_root_password = 1; break;
                case 'B': opts.allow_blank_password = 1; break;
                case 't': opts.require_2fa = 1; break;
                case 'j': opts.no_local_fwd = 1; break;
                case 'k': opts.no_remote_fwd = 1; break;
                case 'a': opts.allow_remote_fwd_any = 1; break;
                case 'i': opts.inetd_mode = 1; break;
                case 'z': opts.disable_qos = 1; break;
                default:
                    fprintf(stderr, "Invalid option -%c\n", c);
                    print_usage();
                    exit(1);
            }
            j++;
            (void)takes_arg; /* silence unused warning */
        }
        i++;
    }
}

static int try_load_hostkey(const char *path) {
    /* Pretend to load a hostkey.  Return 1 on "success", 0 on failure.
     * We only "succeed" if the file exists and is readable. */
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        return 0;
    }
    close(fd);
    return 1;
}

static int load_hostkeys(void) {
    int loaded = 0;
    if (opts.n_keyfiles > 0) {
        for (int i = 0; i < opts.n_keyfiles; i++) {
            if (try_load_hostkey(opts.keyfiles[i])) {
                loaded++;
            } else {
                dblog("Failed loading %s", opts.keyfiles[i]);
            }
        }
    } else {
        static const char *defaults[] = {
            RSA_PRIV_FILENAME,
            ECDSA_PRIV_FILENAME,
            ED25519_PRIV_FILENAME,
            NULL
        };
        for (int i = 0; defaults[i]; i++) {
            if (try_load_hostkey(defaults[i])) {
                loaded++;
            } else {
                dblog("Failed loading %s", defaults[i]);
            }
        }
    }
    return loaded;
}

static int try_listen_port(const char *spec) {
    char *host = NULL, *port = NULL;
    if (split_host_port(spec, &host, &port) != 0) {
        /* Shouldn't happen - we validated earlier */
        dblog("Failed listening on '%s': Error listening: Bad port", spec);
        free(host); free(port);
        return 0;
    }

    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_PASSIVE;
    int gaierr = getaddrinfo(host, port, &hints, &res);
    if (gaierr != 0) {
        dblog("Failed listening on '%s': Error resolving: %s", port, gai_strerror(gaierr));
        free(host); free(port);
        return 0;
    }

    int any_bound = 0;
    const char *last_err = NULL;
    char errbuf[128];
    for (struct addrinfo *r = res; r; r = r->ai_next) {
        int fd = socket(r->ai_family, r->ai_socktype, r->ai_protocol);
        if (fd < 0) {
            last_err = strerror(errno);
            continue;
        }
        int one = 1;
        setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
        if (bind(fd, r->ai_addr, r->ai_addrlen) != 0) {
            snprintf(errbuf, sizeof errbuf, "%s", strerror(errno));
            last_err = errbuf;
            close(fd);
            continue;
        }
        if (listen(fd, 20) != 0) {
            snprintf(errbuf, sizeof errbuf, "%s", strerror(errno));
            last_err = errbuf;
            close(fd);
            continue;
        }
        any_bound = 1;
        /* leave the socket open - we will close on exit */
    }
    freeaddrinfo(res);

    if (!any_bound) {
        dblog("Failed listening on '%s': Error listening: %s",
              port, last_err ? last_err : "Unknown error");
    }
    free(host); free(port);
    return any_bound;
}

static volatile sig_atomic_t caught_signal = 0;
static void signal_handler(int sig) {
    (void)sig;
    caught_signal = 1;
}

int main(int argc, char **argv) {
    prog_name = argv[0];

    parse_args(argc, argv);

    /* Banner file check */
    if (opts.banner_file) {
        int fd = open(opts.banner_file, O_RDONLY);
        if (fd < 0) {
            dblog("Error opening banner file '%s'", opts.banner_file);
        } else {
            close(fd);
        }
    }

    if (opts.forced_command) {
        dblog("Forced command set to '%s'", opts.forced_command);
    }

    if (opts.bind_iface) {
        dblog("Binding to interface '%s'", opts.bind_iface);
    }

    if (opts.restrict_group) {
        errno = 0;
        struct group *g = getgrnam(opts.restrict_group);
        if (!g) {
            early_exit("Cannot restrict logins to group '%s' as the group does not exist",
                       opts.restrict_group);
        }
    }

    int loaded = load_hostkeys();
    if (loaded == 0) {
        early_exit("No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");
    }

    /* Listen on configured ports. */
    int n_listens = 0;
    if (opts.n_ports == 0) {
        if (try_listen_port(DEFAULT_PORT)) n_listens++;
    } else {
        for (int i = 0; i < opts.n_ports; i++) {
            if (try_listen_port(opts.ports[i])) n_listens++;
        }
    }
    if (n_listens == 0) {
        early_exit("No listening ports available.");
    }

    if (opts.no_fork || opts.inetd_mode) {
        dblog("Not backgrounding");
    } else {
        dblog("Running in background");
        pid_t pid = fork();
        if (pid < 0) {
            early_exit("fork() failed");
        }
        if (pid > 0) {
            /* Parent exits immediately with success. */
            _exit(0);
        }
        /* Child - detach from terminal. */
        setsid();
        int devnull = open("/dev/null", O_RDWR);
        if (devnull >= 0) {
            dup2(devnull, 0);
            dup2(devnull, 1);
            dup2(devnull, 2);
            if (devnull > 2) close(devnull);
        }
    }

    /* Set up signal handlers so we can log "Terminated by signal". */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);

    /* We don't implement SSH; just wait for signals / data. */
    while (!caught_signal) {
        pause();
    }

    early_exit("Terminated by signal");
    return 1;
}
